import React, { useEffect, useState } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import Dashboard from './components/Dashboard';
import Analytics from './components/Analytics';
import About from './components/About';
import Features from './components/Features';
import Team from './components/Team';
import Footer from './components/Footer';

function App() {
  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const handleMouseMove = (e) => {
      setMousePosition({
        x: e.clientX,
        y: e.clientY,
      });
    };

    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  return (
    <div className="relative min-h-screen bg-[#050508] text-white overflow-hidden font-sans">
      {/* Dynamic background glow */}
      <div 
        className="pointer-events-none fixed inset-0 z-0 transition-opacity duration-300"
        style={{
          background: `radial-gradient(600px circle at ${mousePosition.x}px ${mousePosition.y}px, rgba(0, 243, 255, 0.05), transparent 40%)`
        }}
      />
      
      {/* Grid background */}
      <div className="fixed inset-0 z-0 bg-[url('data:image/svg+xml;base64,')] opacity-50" />

      <div className="relative z-10">
        <Navbar />
        <main>
          <Hero />
          <Dashboard />
          <Analytics />
          <About />
          <Features />
          <Team />
        </main>
        <Footer />
      </div>
    </div>
  );
}

export default App;
